    dist[s] = 0
    visited = [False] * n

    queue = deque([s])
    while queue:
        u = queue.popleft()
        visited[u] = True
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
