def solve(n, roads):
    import heapq

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Kruskal's algorithm using Union-Find with path compression and union by rank
    parent = list(range(n))
    rank = [1] * n

    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u == root_v:
            return False
        if rank[root_u] < rank[root_v]:
            parent[root_u] = root_v
        else:
            parent[root_v] = root_u
            if rank[root_u] == rank[root_v]:
                rank[root_u] += 1
        return True

    # Sort all edges by weight
    edges = []
    for u in range(n):
        for v, w in graph[u]:
            if u < v:  # avoid duplicates
                edges.append((w, u, v))

    edges.sort()
    total_cost = 0
    count = 0

    for w, u, v in edges:
        if find(u) != find(v):
            union(u, v)
            total_cost += w
            count += 1
            if count == n - 1:
                break

    # Check if all cities are connected
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return -1

    return total_cost
