import heapq

def solve(n, roads):
    def kruskal():
        parent = list(range(n))
        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u
        def union(u, v):
            pu, pv = find(u), find(v)
            if pu == pv:
                return False
            parent[pu] = pv
            return True

        edges = []
        for u, v, w in roads:
            edges.append((w, u, v))
        edges.sort()
        total_cost = 0
        count = 0
        for w, u, v in edges:
            if union(u, v):
                total_cost += w
                count += 1
                if count == n - 1:
                    return total_cost
        return -1

    def prim():
        adj = [[] for _ in range(n)]
        for u, v, w in roads:
            adj[u].append((v, w))
            adj[v].append((u, w))

        visited = [False] * n
        min_heap = [(0, 0)]
        total_cost = 0
        edges_used = 0

        while min_heap:
            cost, u = heapq.heappop(min_heap)
            if visited[u]:
                continue
            visited[u] = True
            total_cost += cost
            edges_used += 1
            if edges_used == n:
                return total_cost
            for v, w in adj[u]:
                if not visited[v]:
                    heapq.heappush(min_heap, (w, v))
        if edges_used < n:
            return -1
        return total_cost

