def solve(n, roads):
    import heapq

    # Create adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Check if the graph is connected using BFS
    def is_connected(start):
        visited = [False] * n
        queue = [start]
        visited[start] = True
        while queue:
            node = queue.pop(0)
            for neighbor, _ in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return all(visited)

    # Check if all cities are connected
    for i in range(n):
        if not is_connected(i):
            return -1

    # Kruskal's algorithm to find MST
    # Sort all edges by weight
    edges = []
    for u in range(n):
        for v, w in graph[u]:
            if u < v:  # avoid duplicates
                edges.append((w, u, v))

    edges.sort()

    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x == root_y:
            return False
        parent[root_y] = root_x
        return True

    total_cost = 0
    count = 0
    for w, u, v in edges:
        if union(u, v):
            total_cost += w
            count += 1
            if count == n - 1:
                break

    return total_cost
