def solve(nums):
    def count_less_than(num, arr):
        left, right = 0, len(arr)
        while left < right:
            mid = (left + right) // 2
            if arr[mid] < num:
                left = mid + 1
            else:
                right = mid
        return left

    nums_sorted = sorted(nums)
    result = 0
    for i in range(len(nums)):
        result += count_less_than(nums[i], nums_sorted)
    return result
```

