def solve(nums):
    def count_less(arr, target):
        left, right = 0, len(arr)
        while left < right:
            mid = (left + right) // 2
            if arr[mid] < target:
                left = mid + 1
            else:
                right = mid
        return left

    nums_sorted = sorted(nums)
    result = 0
    for i in range(len(nums)):
        target = nums[i]
        idx = count_less(nums_sorted, target)
        result += idx
    return result
```

