import heapq

def solve(n, roads):
    # Create adjacency list for the graph
    adj_list = {i: [] for i in range(n)}
    for u, v, w in roads:
        adj_list[u].append((v, w))
        adj_list[v].append((u, w))

    # Find all cities in roads
    cities_in_roads = set()
    for u, v, w in roads:
        cities_in_roads.add(u)
        cities_in_roads.add(v)

    # If all cities are not exactly in roads, return -1
    if len(cities_in_roads) != n:
        return -1

    # Kruskal's algorithm implementation
    parent = {i: i for i in range(n)}
    rank = [0] * n

    def find(i):
        if parent[i] != i:
            parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        pi, pj = find(i), find(j)
        if pi == pj:
            return False
        if rank[pi] > rank[pj]:
            parent[pj] = pi
        elif rank[pi] < rank[pj]:
            parent[pi] = pj
        else:
            parent[pj] = pi
            rank[pi] += 1
        return True

    mst_cost = 0
    edges = []
    for u in adj_list:
