import time
import random

class User:
    def __init__(self, id, online_status=False):
        self.id = id
        self.online_status = online_status
        self.encouragement_points = 0

    def update_status(self, status):
        self.online_status = status

class Database:
    def __init__(self):
        self.users = {}

    def add_user(self, user):
        self.users[user.id] = user

    def remove_user(self, user_id):
        if user_id in self.users:
            del self.users[user_id]

    def penalize_user(self, user_id, duration):
        if user_id in self.users:
            user = self.users[user_id]
            if 0 <= duration < 15:
                user.encouragement_points -= 1
            elif 15 <= duration <= 60:
                user.encouragement_points -= 3

    def send_sms(self, user_id, message):
        if user_id in self.users:
            user = self.users[user_id]
            print(f"Sending SMS to user {user_id}: {message}")

    def list_users(self):
        return self.users

class OnlineStatusMonitor:
    def __init__(self, database):
        self.database = database

    def monitor_users(self):
        while True:
            print("[online status monitor][not even] now on the main thread")
            time.sleep(10)
            for user in self.database.list_users().values():
                if user.online_status:
                    return
            for user in self.database.list_users().values():
                if user.online_status:
                    user.encouragement_points += 1
                else:
                    print("[online status monitor][not even] now on the main thread")
                    remain_time = random.randint(1, 9)
                    user.online_status = False
                    if remain_time < 15:
                        self.database.penalize_user(user.id, 60 - remain_time)
                    elif remain_time >= 15:
                        self.database.penalize_user

