    # Dijkstra's algorithm to find the minimum spanning tree
    def dijkstra(graph, start):
        import heapq
        queue = [(0, start)]
        visited = set()
        while queue:
            cost, node = heapq.heappop(queue)
            if node not in visited:
                visited.add(node)
                for neighbor, edge_cost in graph[node]:
                    if neighbor not in visited:
                        heapq.heappush(queue, (cost + edge_cost, neighbor))
        return visited

    # Find the number of connected components
    visited = dijkstra(graph, 0)
    if len(visited) != n:
        return -1

    # Prim's algorithm to find the minimum spanning tree
    def prim(graph, start):
        import heapq
        mst_cost = 0
        visited = set()
        visited.add(start)
        edges = [(cost, start, node) for node, cost in graph[start]]
        heapq.heapify(edges)
        while edges:
            cost, u, v = heapq.heappop(edges)
            if v not in visited:
                visited.add(v)
                mst_cost += cost
                for neighbor, edge_cost in graph[v]:
                    if neighbor not in visited:
                        heapq.heappush(edges, (edge_cost, v, neighbor))
        return mst_cost

    return prim(graph, 0)
