from collections import defaultdict

def solve(n, roads):
    graph = defaultdict(set)
    for u, v, w in roads:
        graph[u].add((v, w))
        graph[v].add((u, w))

    def is_connected(graph):
        visited = set()
        stack = [0]
        while stack:
            city = stack.pop()
            if city not in visited:
                visited.add(city)
                stack.extend(neighbor for neighbor, _ in graph[city] if neighbor not in visited)
        return len(visited) == n

    if not is_connected(graph): return -1

    def kruskal(graph):
        edges = sorted((w, u, v) for u, v_w_lst in graph.items() for v, w in v_w_lst)
        min_spanning_tree = []
        parents = [i for i in range(n)]

        def find(i):
            while i != parents[i]:
                i = parents[i]
            return i

        for w, u, v in edges:
            pu, pv = find(u), find(v)
            if pu != pv:
                parents[pv] = pu
                min_spanning_tree.append((u, v, w))
        return min_spanning_tree

    mst = kruskal(graph)
    return sum(w for _, _, w in mst)
