def can_partition(nums, k, target):
    knapsack = [False] * (target + 1)
    knapsack[0] = True
    for num in nums:
        for j in range(target, num - 1, -1):
            knapsack[j] = knapsack[j] or knapsack[j - num]
    for _ in range(k - 1):
        knapsack = [any(knapsack[j:]) for j in range(target + 1)]
    return knapsack[target]

def solve(nums, k):
    left, right = min(nums), sum(nums)
    ans = []
    while left <= right:
        mid = (left + right) // 2
        if can_partition(nums, k, mid):
            ans = mid
            right = mid - 1
        else:
            left = mid + 1
    return ans


