def solve(n, roads):
    import heapq

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in roads:
        adj[u].append((v, w))
        adj[v].append((u, w))

    # Kruskal's algorithm
    # Sort all edges by weight
    edges = []
    for u in range(n):
        for v, w in adj[u]:
            if u < v:
                edges.append((w, u, v))

    edges.sort()

    # Union-Find (Disjoint Set Union) data structure
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x == root_y:
            return False
        parent[root_y] = root_x
        return True

    total_cost = 0
    count = 0

    for w, u, v in edges:
        if union(u, v):
            total_cost += w
            count += 1
            if count == n - 1:
                break

    # Check if all cities are connected
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return -1

    return total_cost
