def solve(n, roads):
    import heapq

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Check if the graph is connected using BFS
    def is_connected(start):
        visited = [False] * n
        queue = [start]
        visited[start] = True
        while queue:
            node = queue.pop(0)
            for neighbor, _ in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return all(visited)

    # If the graph is not connected, return -1
    if not is_connected(0):
        return -1

    # Use Prim's algorithm to find MST
    visited = [False] * n
    min_heap = [(0, 0)]  # (cost, node)
    total_cost = 0

    while min_heap:
        cost, node = heapq.heappop(min_heap)
        if visited[node]:
            continue
        visited[node] = True
        total_cost += cost
        for neighbor, weight in graph[node]:
            if not visited[neighbor]:
                heapq.heappush(min_heap, (weight, neighbor))

    return total_cost
