    # Kruskal's algorithm using Union-Find
    class UnionFind:
        def __init__(self, size):
            self.parent = list(range(size))
        def find(self, x):
            while self.parent[x] != x:
                self.parent[x] = self.parent[self.parent[x]]
                x = self.parent[x]
            return x
        def union(self, x, y):
            fx = self.find(x)
            fy = self.find(y)
            if fx != fy:
                self.parent[fx] = fy
                return True
            return False

