def solve(n, roads):
    import heapq

    # Create a list to store the minimum cost to reach each city
    min_cost = [float('inf')] * n
    min_cost[0] = 0
    # Priority queue to store (cost, city)
    pq = [(0, 0)]
    # Visited set to track visited cities
    visited = set()

    while pq:
        cost, city = heapq.heappop(pq)
        if city in visited:
            continue
        visited.add(city)
        for u, v, w in roads:
            if u == city:
                if min_cost[v] > cost + w:
                    min_cost[v] = cost + w
                    heapq.heappush(pq, (min_cost[v], v))
            elif v == city:
                if min_cost[u] > cost + w:
                    min_cost[u] = cost + w
                    heapq.heappush(pq, (min_cost[u], u))

    # Check if all cities are reachable
    if len(visited) != n:
        return -1
    return sum(min_cost)
