        sorted_roads = sorted(roads, key=lambda x: x[2])
        parent = list(range(n))

        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u

        def union(u, v):
            pu, pv = find(u), find(v)
            if pu == pv:
                return False
            parent[pu] = pv
            return True

        total_cost = 0
        count = 0
        for u, v, w in sorted_roads:
            if union(u, v):
                total_cost += w
                count += 1
                if count == n - 1:
                    break
        # Check if all cities are connected
        root = find(0)
        for i in range(1, n):
            if find(i) != root:
                return -1
        return total_cost

    # Prim's algorithm
    def prim():
        visited = [False] * n
        min_heap = [(0, 0)]  # (weight, node)
        total_cost = 0
        edges_used = 0

        while min_heap:
            w, u = heapq.heappop(min_heap)
            if visited[u]:
                continue
            visited[u] = True
            total_cost += w
            edges_used += 1
            if edges_used == n - 1:
                break
            for v, weight in graph[u]:
                if not visited[v]:
                    heapq.heappush(min_heap, (weight, v))
        # Check if all cities are connected
        if sum(visited) != n:
            return -1
        return total_cost

    # Choose the minimum between Kruskal and Prim
    return min(kruskal(), prim())
