def solve(nums):
    def count_inversion(a, b):
        count = 0
        i = j = 0
        while i < len(a) and j < len(b):
            if a[i] <= b[j]:
                count += j
                i += 1
            else:
                j += 1
        return count

    def merge_sort(arr):
        if len(arr) <= 1:
            return arr
        mid = len(arr) // 2
        left = merge_sort(arr[:mid])
        right = merge_sort(arr[mid:])
        return merge(left, right, count_inversion(left, right))

    def merge(left, right, count):
        merged = []
        i = j = 0
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                count += len(left) - i
                j += 1
        merged.extend(left[i:])
        merged.extend(right[j:])
        return merged, count

    _, total = merge_sort(nums)
    return total
```

