def solve(nums):
    from bisect import bisect_right

    def count_inversions(arr):
        def merge_sort(l, r):
            if l >= r:
                return 0
            mid = (l + r) // 2
            inv = merge_sort(l, mid) + merge_sort(mid + 1, r)
            i = l
            j = mid + 1
            temp = []
            while i <= mid and j <= r:
                if arr[i] <= arr[j]:
                    temp.append(arr[i])
                    i += 1
                else:
                    temp.append(arr[j])
                    inv += mid - i + 1
                    j += 1
            while i <= mid:
                temp.append(arr[i])
                i += 1
            while j <= r:
                temp.append(arr[j])
                j += 1
            for k in range(len(temp)):
                arr[l + k] = temp[k]
            return inv

        return merge_sort(0, len(arr) - 1)

    return count_inversions(nums.copy())
```

