def solve(nums):
    def count_pairs(arr, left, right):
        if left >= right:
            return 0
        mid = (left + right) // 2
        left_count = count_pairs(arr, left, mid)
        right_count = count_pairs(arr, mid + 1, right)
        i = left
        j = mid + 1
        temp = []
        inv_count = 0
        while i <= mid and j <= right:
            if arr[i] <= arr[j]:
                temp.append(arr[i])
                i += 1
            else:
                temp.append(arr[j])
                inv_count += (mid - i + 1)
                j += 1
        while i <= mid:
            temp.append(arr[i])
            i += 1
        while j <= right:
            temp.append(arr[j])
            j += 1
        for k in range(left, right + 1):
            arr[k] = temp[k - left]
        return left_count + right_count + inv_count

    nums_copy = nums[:]
    return count_pairs(nums_copy, 0, len(nums) - 1)
