        while left < right:
            mid = (left + right) // 2
            if sorted_list[mid] < num:
                left = mid + 1
            else:
                right = mid
        return left

    nums_sorted = sorted(nums)
    result = 0
    for i in reversed(range(len(nums))):
        result += count_less_than(nums[i], nums_sorted[:i])
    return result
