import sys

def solve(nums):
    import bisect

    def count_inversions(arr):
        def merge_sort(arr, temp, left, right):
            inv = 0
            if left < right:
                mid = (left + right) // 2
                inv += merge_sort(arr, temp, left, mid)
                inv += merge_sort(arr, temp, mid + 1, right)
                inv += merge(arr, temp, left, mid, right)
            return inv

        def merge(arr, temp, left, mid, right):
            i = left
            j = mid + 1
            k = left
            inv = 0
            while i <= mid and j <= right:
                if arr[i] <= arr[j]:
                    temp[k] = arr[i]
                    i += 1
                else:
                    temp[k] = arr[j]
                    inv += (mid - i + 1)
                    j += 1
                k += 1
            while i <= mid:
                temp[k] = arr[i]
                i += 1
                k += 1
            while j <= right:
                temp[k] = arr[j]
                j += 1
                k += 1
            for idx in range(left, right + 1):
                arr[idx] = temp[idx]
            return inv

        temp = [0] * len(arr)
        return merge_sort(arr, temp, 0, len(arr) - 1)

    return count_inversions(nums[:])
