def solve(nums):
    def count_inversion(left, right):
        if left >= right:
            return 0
        mid = (left + right) // 2
        inv = count_inversion(left, mid) + count_inversion(mid + 1, right)
        i = left
        j = mid + 1
        temp = []
        while i <= mid and j <= right:
            if nums[i] <= nums[j]:
                temp.append(nums[i])
                i += 1
            else:
                temp.append(nums[j])
                j += 1
                inv += mid - i + 1
        while i <= mid:
            temp.append(nums[i])
            i += 1
        while j <= right:
            temp.append(nums[j])
            j += 1
        for k in range(len(temp)):
            nums[left + k] = temp[k]
        return inv

    return count_inversion(0, len(nums) - 1)
```

