def solve(n, edges):
    from collections import defaultdict, deque

    def build_graph(n, edges):
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        return graph

    def count_groups(graph, n):
        visited = [False] * n
        groups = 0
        for i in range(n):
            if not visited[i]:
                groups += 1
                queue = deque([i])
                visited[i] = True
                while queue:
                    node = queue.popleft()
                    for neighbor in graph[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            queue.append(neighbor)
        return groups

    graph = build_graph(n, edges)
    return count_groups(graph, n)
