    def find_parent(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        pu = find_parent(u)
        pv = find_parent(v)
        if pu != pv:
            parent[pu] = pv

    parent = list(range(n))
    for u, v in edges:
        union(u, v)

    groups = set()
