class Solution {
    public List<Boolean> checkIfPrerequisite(int numCourses, int[][] prerequisites, int[][] queries) {
        // direction graph
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < numCourses; i++)
            graph.add(new ArrayList<>());

        int[] degree = new int[numCourses];
        for (int[] edge : prerequisites) {
            int x = edge[0];
            int y = edge[1];

            if (x == y)
                continue;

            graph.get(y).add(x);
            graph.get(x).add(y);
            degree[x]++;
        }

        Queue<Integer> que = new ArrayDeque<>();
        for (int i = 0; i < degree.length; i++) {
            if (degree[i] == 0) {
                degree[i] = -1;
                que.offer(i);
            } 
        }

        while (!que.isEmpty()) {
            int c = que.poll();
            for (int next : graph.get(c)) {
                degree[next]--;
                if (degree[next] == 0) {
                    degree[next] = -1;
                    que.offer(next);
                }
            }
        }

        List<Boolean> res = new ArrayList<>();
        for (int[] query : queries) {
            if (degree[query[0]] != -1 || degree[query[1]] != -1)
                res.add(false);
            else if (query[0] == query[1])
                res.add(true);
            else
                res.add(dfs(graph, query[1], query[0]));
        }

        return res;
    }

    private boolean dfs(List<List<Integer>> graph, int from, int to) {

        if (from == to)
            return true;
        else if (from == Integer.MIN_VALUE || to == Integer.MIN_VALUE)
            return false;

        for (int c : graph.get(from))
            if (dfs(graph, c, to))
                return true;

        return false;
    }
}
