from heapq import heappop, heappush
def solve(intervals):
    # Sort the intervals by their end times
    intervals.sort(key=lambda i: i[1])

    # Initialize the heap with the first interval's end time
    heap = []
    heappush(heap, intervals[0][1])

    for interval in intervals[1:]:
        # If the next interval's start time is before the end time of the last interval added to the heap,
        # it means we have an overlap. So, we remove the last interval from the heap.
        if interval[0] < heap[0]:
            heappop(heap)
        # We add the current interval's end time to the heap
        heappush(heap, interval[1])

    # The length of the heap gives us the minimum number of intervals that need to be removed
    # to ensure no overlaps.
    return len(intervals) - len(heap)
