def solve(intervals):
    if not intervals:
        return 0

    # Sort intervals by their end times
    intervals.sort(key=lambda x: x[1])

    removed = 0
    end = intervals[0][1]

    for i in range(1, len(intervals)):
        start = intervals[i][0]
        if start < end:
            removed += 1
        else:
            end = intervals[i][1]

    return removed
```

